      font-weight:600;
    ">
      Dentre todos os seriais localizados, não foi encontrado nenhum item dentro do período de garantia.
    </div>
  `
  : '';

// 🔹 BOTÃO DE DOWNLOAD DO EXCEL
const htmlDownload = fileLink
  ? `
