// ═══════════════════════════════════════════════════
// 3. HTML FINAL
// ═══════════════════════════════════════════════════
// ── BOTÕES DE RESPOSTA DO CLIENTE (e-mail HTTP -> gateway -> webhook do n8n) ──
const URL_APROVAR = String($('Config Gateway').first().json.URL_APROVAR || '');
const URL_REPROVAR = String($('Config Gateway').first().json.URL_REPROVAR || '');
if (!/^https?:\/\//i.test(URL_APROVAR) || !/^https?:\/\//i.test(URL_REPROVAR)) {
  throw new Error("Configure URL_APROVAR e URL_REPROVAR no nó 'Config Gateway'");
}
