// 1. Captura o primeiro item de entrada enviado pelo nó anterior
const itemEntrada = $('TratarDados3').first().json;

// 2. Coleta o ID do processo e a lista de objetos estruturados
const processo = itemEntrada["id_processo"] || "";
const listaSeriais = Array.isArray(itemEntrada["seriais"])
  ? itemEntrada["seriais"]
  : [];

// 3. Trata e filtra os números de série
const seriaisValidos = listaSeriais
  .map(item => {
    return String((item && item.serial) || "")
      .toUpperCase()
      .trim();
  })
  .filter(serial => {
    // Ignora valores vazios
    if (!serial) {
      return false;
    }
    // Ignora textos de orientação enviados como serial
    if (
      serial.includes("NÚMERO DE SÉRIE") ||
      serial.includes("NUMERO DE SERIE") ||
      serial.includes("VERIFICAR NA ETIQUETA") ||
