// 🔹 Helper: parse "DD/MM/YYYY" -> Date
function parseDataBR(str) {
  if (!str) return null;
  const [d, m, y] = String(str).trim().split('/');
  if (!d || !m || !y) return null;
  const date = new Date(Number(y), Number(m) - 1, Number(d));
  return isNaN(date.getTime()) ? null : date;
}

const hoje = new Date();
hoje.setHours(0, 0, 0, 0);

// 🔹 Formata data como DD/MM/AAAA (aceita Date, ISO ou texto já formatado)
function fmtBR(d) {
  return String(d.getDate()).padStart(2, '0') + '/' + String(d.getMonth() + 1).padStart(2, '0') + '/' + d.getFullYear();
}
function fmtBRvalor(v) {
  if (!v) return '';
  const s = String(v).trim();
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(s)) return s;
  const d = new Date(v);
  return isNaN(d.getTime()) ? s : fmtBR(d);
}
// 🔹 Contrato / aditivo só aparecem para LOCAÇÃO
function ehLocacao(r) {
  return String(r.MODALIDADE || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toUpperCase().includes('LOCA');
}
function camposContrato(r) {
  return ehLocacao(r) ? {
    CONTRATO: String(r.CONTRATO || '').trim(),
    ADITIVO: String(r.ADITIVO || '').trim(),
    DATA_ADITIVO: fmtBRvalor(r.DATA_ADITIVO),
    TEMPO_CONTRATO: r.TEMPO_CONTRATO
  } : {};
}


// 🔹 Recalcula garantia com fallback de 365 dias quando o cadastro vier 0/nulo
function calcularGarantia(r) {
  const dataExp = parseDataBR(r.DATA_EXP);

  // Ignora expedições "sujas" tipo 01/01/1900 (sem NF real)
  if (!dataExp || dataExp.getFullYear() < 2000) {
    return {
      garantiaDias: r.GARANTIA_CADASTRO_DIAS,
      dataGarantia: fmtBRvalor(r.DATA_GARANTIA_DATE),
      garantia: 'NAO'
    };
  }

  // Usa o valor real cadastrado no produto, sem fallback —
  // 0 dias significa garantia vencendo na própria data de expedição
  const garantiaDias = Number(r.GARANTIA_CADASTRO_DIAS) || 0;

  const dataGarantia = new Date(dataExp);
  dataGarantia.setDate(dataGarantia.getDate() + garantiaDias);

  const emGarantia = dataGarantia >= hoje;

  return {
    garantiaDias,
    dataGarantia: fmtBR(dataGarantia),
    garantia: emGarantia ? 'SIM' : 'NAO'
  };
}

// 🔹 Calcula garantia corrigida para cada registro
const dadosCorrigidos = dados.map(r => ({
  ...r,
  _garantiaCalc: calcularGarantia(r)
}));

// 🔹 ORDENAÇÃO: Fora de Garantia primeiro
const dadosOrdenados = [...dadosCorrigidos].sort((a, b) => {
  const aFora = a._garantiaCalc.garantia === 'NAO';
  const bFora = b._garantiaCalc.garantia === 'NAO';
  if (aFora && !bFora) return -1;
  if (!aFora && bFora) return 1;
  return 0;
});

// Retorna o mapeamento correto dos campos desejados
return dadosOrdenados.map(r => {
  const g = r._garantiaCalc;
  return {
    STATUS_GARANTIA: g.garantia === 'SIM' ? 'EM GARANTIA' : 'FORA GARANTIA',
    ID_PROCESSO: r.ID_PROCESSO,
    SERIAL: r.SERIAL,
