  const subject = email.subject || "";

  // Extrai o número CRG do assunto (ex: "CRG-2200 Analise de seriais")
  const match = subject.match(/CRG-(\d+)/i);
  if (!match) continue;

  const crgNumber = match[1];
  const crgCode = `CRG-${crgNumber}`;

  // Filtra os binários: só mantém o arquivo que tem "CRG-XXXX" no nome
  // e renomeia a key para o código CRG
  const filteredBinary = {};

  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const fileName = item.binary[key].fileName || "";
      if (fileName.toUpperCase().includes(crgCode.toUpperCase())) {
        filteredBinary[crgCode] = item.binary[key]; // key vira "CRG-2200"
      }
    }
  }

  // Só retorna se encontrou o arquivo do CRG
  if (Object.keys(filteredBinary).length === 0) continue;

  results.push({
    json: {
      crgCode,
      crgNumber,
      subject,
      from: email.from?.emailAddress?.address || email.from || "",
      receivedDateTime: email.receivedDateTime || "",
      fileName: Object.values(filteredBinary)[0].fileName,
      fabricante: "Nokia",
    },
    binary: filteredBinary,
  });
}

return results;

const itens = $input.all();
const listaEquipamentos = [];
const listaDuplicados = [];
const seriaisVistos = new Set();

let idProcesso = '';
let fabricante = '';

try {
