  idProcesso = form['N° do CRG'];
  fabricante = form['Fabricante'];
} catch (e) {
  const body = $('Webhook').first().json.body;
  idProcesso = body['N° Do CRG'] || '';
  fabricante = body['Fabricante'] || body['fabricante'] || '';
}

for (let i = 1; i < itens.length; i++) {
  const dadosOriginais = itens[i].json;
  const chaveSerial = Object.keys(dadosOriginais)[0];
  const serial = dadosOriginais[chaveSerial] ? dadosOriginais[chaveSerial].toString().trim() : "";
  const mac = dadosOriginais["__EMPTY"] ? dadosOriginais["__EMPTY"].toString().trim() : "";

  if (serial) {
    const objetoEquipamento = { serial, mac };
    if (seriaisVistos.has(serial)) {
      listaDuplicados.push(objetoEquipamento);
    } else {
      seriaisVistos.add(serial);
      listaEquipamentos.push(objetoEquipamento);
    }
  }
}

return [{
  json: {
    id_processo: idProcesso,
    fabricante: fabricante,
    seriais: listaEquipamentos,
    seriais_duplicados: listaDuplicados
  }
}];

