parameters.jsCode:
// Captura o item COMPLETO (não apenas o .json) para ter acesso à aba Binary
// ── Detecta qual trigger disparou esta execução ──────────
// Só o node do trigger que efetivamente rodou tem dado disponível;
// referenciar o outro sem try/catch quebra a execução.
let outlookItem = null;

try {
  outlookItem = $('Validação ').first();
} catch (e) {
  // Validação 1 não disparou nesta execução, tenta a próxima
}

if (!outlookItem) {
  try {
    outlookItem = $('Validação 3').first();
  } catch (e) {
    // nenhum dos dois disparou — não deveria acontecer
  }
}

if (!outlookItem) {
  throw new Error('Nenhum trigger de validação (Validação 1 ou Validação 2) foi encontrado nesta execução.');
}

const dadosJson = outlookItem.json;
const binary = outlookItem.binary || {};

const novoBinary = {};
let pdfCount = 0;
let xmlCount = 0;

for (const [chave, arquivo] of Object.entries(binary)) {
  const nome = (arquivo.fileName || '').toLowerCase();
  const mime = (arquivo.mimeType || '').toLowerCase();

  if (nome.endsWith('.pdf') || mime === 'application/pdf') {
    // Alinhado com o seu nó de base64 que busca chaves que começam com 'pdf'
    novoBinary[`pdf_${pdfCount}`] = arquivo;
    pdfCount++;
  } else if (nome.endsWith('.xml') || mime === 'text/xml' || mime === 'application/xml') {
    novoBinary[`xml_${xmlCount}`] = arquivo;
    xmlCount++;
  }
}

// conversa sem nota (nenhum PDF/XML): ignora, não inicia validação
if (pdfCount + xmlCount === 0) return [];

return [{
  json: {
    ...dadosJson, // Mantém os dados originais do e-mail vivos se precisar deles adiante
    total_pdfs: pdfCount,
    total_xmls: xmlCount,
    arquivos: Object.entries(novoBinary).map(([k, v]) => ({ chave: k, nome: v.fileName }))
  },
  binary: novoBinary
}];

const items = $input.all();
const notas = [];

// ── extrai razão social + endereço completo do EMITENTE da NF ──────────
function extrairEmitente(texto) {
  const result = {
    razao_emitente: '',
    endereco_emitente: '',
    bairro_emitente: '',
    cep_emitente: '',
    municipio_emitente: '',
    uf_emitente: '',
    fone_emitente: ''
  };

  const blocoMatch = texto.match(/IDENTIFICA[ÇC][ÃA]O DO EMITENTE\s*\n([\s\S]*?)(?=\n\s*DANFE|\n\s*Documento Auxiliar)/i);
  if (!blocoMatch) return result;

  const linhas = blocoMatch[1].split('\n').map(l => l.trim()).filter(Boolean);

  const enderecoRegex = /^(Avenida|Av\.?|Rua|R\.?|Rod\.?|Rodovia|Alameda|Al\.?|Travessa|Tv\.?|Pra[çc]a|Estrada|Est\.?)\b/i;
  let idxEndereco = linhas.findIndex(l => enderecoRegex.test(l));
  if (idxEndereco === -1) {
    idxEndereco = linhas.findIndex(l => /,\s*\d+\s*$/.test(l));
  }
  if (idxEndereco === -1) idxEndereco = linhas.length;

  result.razao_emitente = linhas.slice(0, idxEndereco).join(' ').replace(/\s+/g, ' ').trim();

  if (idxEndereco < linhas.length) {
    result.endereco_emitente = linhas[idxEndereco];
  }

  for (let i = idxEndereco + 1; i < linhas.length; i++) {
    const m = linhas[i].match(/^(.*?)\s*-\s*(?:CEP:?\s*)?(\d{5}-?\d{3})\s*$/i);
    if (m) {
      result.bairro_emitente = m[1].trim();
      result.cep_emitente = m[2];
      if (linhas[i + 1]) {
        const m2 = linhas[i + 1].match(/^(.*?)\s*-\s*([A-Z]{2})\s+Fone(?:\/Fax)?:?\s*(.*)$/i);
        if (m2) {
          result.municipio_emitente = m2[1].trim();
          result.uf_emitente = m2[2].trim();
          result.fone_emitente = m2[3].trim();
        }
      }
      break;
    }
  }

  return result;
}

// ── CNPJ da Livetech/WDC — SEMPRE o destinatário nesta operação ──────
// Usar essa constante em vez de heurística posicional é o que resolve
// definitivamente o problema: templates diferentes de DANFE colocam os
// rótulos ("DESTINATÁRIO", "CNPJ/CPF") em ordens diferentes em relação
// aos valores no texto extraído, então "primeiro CNPJ" / "último CNPJ" /
// "X caracteres depois do rótulo" são heurísticas frágeis. Como o CNPJ
// de destino é sempre o mesmo (fixo), comparamos direto — sem ambiguidade.
const CNPJ_LIVETECH_LIMPO = '05917486000140';

function limparCnpj(c) {
  return (c || '').toString().replace(/\D/g, '');
}

for (const item of items) {
  let texto = item.json.text || '';
  if (!texto) continue;

  // ── descarta a segunda renderização "espelho" (imagem/OCR do DANFE) ──
  const rodapeMatch = texto.match(/Powered by TCPDF[^\n]*/i);
  if (rodapeMatch) {
    const fimReal = texto.indexOf(rodapeMatch[0]) + rodapeMatch[0].length;
    texto = texto.substring(0, fimReal);
  }

  function extrair(regex) {
    const m = texto.match(regex);
    if (!m) return '';
    return (m[1] || m[0] || '').trim();
  }

  const cnpjs = [];
  let cm;
  const cReg = /(\d{2}\.\d{3}\.\d{3}\/\d{4}-\d{2})/g;
  while ((cm = cReg.exec(texto)) !== null) cnpjs.push(cm[1]);

  let chaveAcesso = '';
  const chaveMatch = texto.match(/CHAVE\s+DE\s+ACESSO\s*\n([\d\s]+)/i);
  if (chaveMatch) {
    chaveAcesso = chaveMatch[1].replace(/\s/g, '').trim();
    if (chaveAcesso.length > 44) chaveAcesso = chaveAcesso.substring(0, 44);
  }
  if (!chaveAcesso) chaveAcesso = extrair(/(\d{44})/);

  let numNf = extrair(/N[º°]\.?:?[ \t]*(\d+(?:[. ]\d+)*)/i);
  if (numNf) numNf = numNf.replace(/[. ]/g, '').replace(/^0+(?=\d)/, '');

  const serie = extrair(/S[ée]rie\.?:?\s*(\d+)/i);

  let valorTotal = extrair(/VALOR\s+TOT\.?\s+(?:DA\s+)?NOTA\s*\n?\s*R?\$?\s*([\d.,]+)/i);
  if (!valorTotal) valorTotal = extrair(/Valor\s+Total:\s*R\$\s*([\d.,]+)/i);

  const dataEmissao = extrair(/(?:DATA\s+DE\s+EMISS[ÃA]O|Emiss[ãa]o:)\s*\n?\s*(\d{2}\/\d{2}\/\d{4})/i);

  let natureza = extrair(/NATUREZA DA OPERA[ÇC][ÃA]O\s*\n([A-Za-zÀ-ú ().\-\/]+)/i);
  if (!natureza || natureza.length > 80) {
    const nat2 = texto.match(/(Remessa[^,\n]*)/i);
    natureza = nat2 ? nat2[1].trim() : '';
  }

  const crg = extrair(/CRG[- ]?(\d+)/i)
           || extrair(/SOLICITA[ÇC][ÃA]O DE REPARO\s+(\d+)/i)
           || extrair(/SOLICITA[ÇC][ÃA]O DE REPARO(?:\s+OU\s+GARANTIA)?:?\s*(\d+)/i);

  const infoMatch = texto.match(/INFORMA[ÇC][ÕO]ES COMPLEMENTARES\s*\n([\s\S]*?)(?=RESERVADO AO FISCO|Impresso em|$)/i);
  const infoComplementar = infoMatch ? infoMatch[1].trim() : '';

  const nfRefs = [];
  const nfR = /(?:NF|n\.)\s*(?:referenciada\s*n\.\s*)?(\d{5,})/gi;
  let nr;
  while ((nr = nfR.exec(texto)) !== null) nfRefs.push(nr[1]);

  // ── NOVO: CNPJ destinatário/emitente via correspondência com o CNPJ
  // fixo da Livetech, em vez de posição no texto ──
  let cnpjDestinatario = '';
  let cnpjEmitente = '';

  const cnpjLivetechEncontrado = cnpjs.find(c => limparCnpj(c) === CNPJ_LIVETECH_LIMPO);

  if (cnpjLivetechEncontrado) {
    cnpjDestinatario = cnpjLivetechEncontrado;
    cnpjEmitente = cnpjs.find(c => limparCnpj(c) !== CNPJ_LIVETECH_LIMPO) || '';
  } else {
    // Fallback: CNPJ da Livetech não apareceu no texto (não deveria
    // acontecer nesse fluxo) — usa a heurística antiga como último recurso
    cnpjEmitente = cnpjs.length > 0 ? cnpjs[0] : '';
    cnpjDestinatario = cnpjs.length > 1 ? cnpjs[cnpjs.length - 1] : '';
    const destMatch = texto.match(/DESTINAT[ÁA]RIO[\s\S]{0,600}?CNPJ[\s\/]*CPF\s*\n?\s*([\d.\/-]{14,18})/i);
    if (destMatch) cnpjDestinatario = destMatch[1];
  }

  const produtos = [];
  const secao = texto.match(/(?:CÓDIGO\s+(?:PRODUTO\s+)?DESCRIÇÃO|CÓDIGO\s*\nPRODUTO)([\s\S]*?)(?=TRIBUTOS|CÁLCULO DO ISSQN|DADOS (?:ADICIONAIS|DOS PRODUTOS))/i);
  if (secao) {
    const bloco = secao[1];
    const reg1 = /(\d{5,})\s*->\s*([\s\S]*?)(\d{8})\s+(\d{3,4})\s+(\d{4})\s+(\w+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)/g;
    const reg2 = /(\d{3,7})\s+((?:(?!\d{8}\s)[\s\S])+?)\s*(\d{8})\s+(\d{3,4})\s+(\d{4})\s+(\w+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)/g;
    const reg3 = /(\d{3,7})\s+((?:(?!\d{8}\s)[\s\S])+?)\s*(\d{8})\s+(\S{1,6})\s+(\d{4})\s+(\w+)\s+([\d.,]+)\s+([\d.,]+)\s+([\d.,]+)((?:\s+[\d.,]+)*)/g;

    let pm;
    let usouFormato1 = false;
    while ((pm = reg1.exec(bloco)) !== null) {
      usouFormato1 = true;
      produtos.push({
        codigo: pm[1].trim(),
        descricao: pm[2].replace(/\n/g, ' ').replace(/\s+/g, ' ').trim(),
        ncm: pm[3], cst: pm[4], cfop: pm[5], unidade: pm[6],
        quantidade: parseFloat(pm[7].replace(/\./g, '').replace(',', '.')).toString(),
        valor_unitario: pm[8], valor_total: pm[9],
        bc_icms: pm[10], vlr_icms: pm[11], vlr_ipi: pm[12],
        aliq_icms: pm[13], aliq_ipi: pm[14]
      });
    }

    if (!usouFormato1) {
      while ((pm = reg2.exec(bloco)) !== null) {
        const desc = pm[2].replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
        if (desc.includes('DESCRIÇÃO DO PRODUTO') || desc.includes('NCM/SH')) continue;
        produtos.push({
          codigo: pm[1].trim(),
          descricao: desc,
          ncm: pm[3], cst: pm[4], cfop: pm[5], unidade: pm[6],
          quantidade: parseFloat(pm[7].replace(/\./g, '').replace(',', '.')).toString(),
          valor_unitario: pm[8], valor_total: pm[9],
          bc_icms: pm[10], vlr_icms: pm[11], vlr_ipi: pm[12],
          aliq_icms: pm[13], aliq_ipi: pm[14]
        });
      }
    }

    if (produtos.length === 0) {
      while ((pm = reg3.exec(bloco)) !== null) {
        const desc = pm[2].replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();
        if (desc.includes('DESCRIÇÃO DO PRODUTO') || desc.includes('NCM/SH')) continue;
        const tailVals = (pm[10] || '').trim().split(/\s+/).filter(Boolean);
        produtos.push({
          codigo: pm[1].trim(),
          descricao: desc,
          ncm: pm[3], cst: pm[4], cfop: pm[5], unidade: pm[6],
          quantidade: parseFloat(pm[7].replace(/\./g, '').replace(',', '.')).toString(),
          valor_unitario: pm[8], valor_total: pm[9],
          bc_icms: tailVals[0] || '0,00',
          vlr_icms: tailVals[1] || '0,00',
          vlr_ipi: tailVals[2] || '0,00',
          aliq_icms: tailVals[3] || '0,00',
          aliq_ipi: tailVals[4] || '0,00'
        });
      }
    }
  }

  const cfop = produtos.length > 0 ? produtos[0].cfop : extrair(/(\d{4})\s+(?:PC|UN)\s/i);

  const emitente = extrairEmitente(texto);

  notas.push({
    json: {
      cnpj_emitente: cnpjEmitente,
      cnpj_destinatario: cnpjDestinatario,
      numero_nf: numNf,
      serie,
      chave_acesso: chaveAcesso,
      cfop,
      valor_total: valorTotal,
      natureza,
      crg,
      data_emissao: dataEmissao,
      info_complementar: infoComplementar,
      nfs_referencia: [...new Set(nfRefs)],
      produtos,
      razao_emitente: emitente.razao_emitente,
      endereco_emitente: emitente.endereco_emitente,
      bairro_emitente: emitente.bairro_emitente,
      cep_emitente: emitente.cep_emitente,
      municipio_emitente: emitente.municipio_emitente,
      uf_emitente: emitente.uf_emitente,
      fone_emitente: emitente.fone_emitente
    }
  });
}

return notas;

const items = $('Consultar seriais').all();
const grupos = {};
for (const item of items) {
  const dados = item.json;
  if (dados.body && (dados.body.payload || dados.body.crg)) continue;
  const descricao = (dados.DESCRICAO || '').toString().trim();
  const codProd = (dados.COD_PROD || '').toString().trim();
  if (!descricao) continue;
  const chave = codProd || descricao;
  if (!grupos[chave]) {
    grupos[chave] = {
      cod_prod: codProd,
      descricao,
      quantidade: 0,
      valor_unitario: dados.VALOR_UNITARIO || null
    };
  }
  grupos[chave].quantidade++;
}
return Object.values(grupos).map(g => ({ json: g }));

const item = $input.first();
const binary = item.binary || {};
const output = [];

for (const [chave, arquivo] of Object.entries(binary)) {
  if (chave.startsWith('pdf')) {
    output.push({
      json: { arquivo_origem: chave, nome: arquivo.fileName },
      binary: { pdf: arquivo }
    });
  }
}

return output;

// ── Detecta qual trigger disparou esta execução ──────────
// "Validação 1"  → primeira submissão do cliente (subject: "Modelo de nota CRG-...")
// "Validação 2"  → reenvio após correção solicitada (subject: "Correção da nota CRG-...")
// Como só o node do trigger que efetivamente disparou tem dado na execução,
// referenciar o outro sem try/catch quebra o fluxo.
let item = null;
let tipoValidacao = '';

try {
  item = $('Validação ').first().json;
  tipoValidacao = 'primaria';
} catch (e) {
  // Validação 1 não disparou nesta execução, tenta a próxima
}

if (!item) {
  try {
    item = $('Validação 3').first().json;
    tipoValidacao = 'secundaria';
  } catch (e) {
    // nenhum dos dois disparou — não deveria acontecer, mas evita quebra total
  }
}

item = item || {};
const assunto = item.subject || '';

const matchCrg = assunto.match(/CRG[- ]?(\d+)/i);
const crg = matchCrg ? matchCrg[1] : '';

const matchFab = assunto.match(/- ([^-]+)$/);
const fabricante = matchFab ? matchFab[1].trim() : '';

return [{
  json: {
    crg,
    fabricante,
    remetente: item.from?.emailAddress?.address || '',
    remetente_nome: item.from?.emailAddress?.name || '',
    assunto,
    data_recebimento: item.receivedDateTime || '',
    email_id: item.id || '',
    tipo_validacao: tipoValidacao // 'primaria' | 'secundaria'
  }
}];

const produtosCrg = $('TratarDadosSeriais').all().map(i => i.json);
const notas = $('TratarDados6').all().map(i => i.json);

const CNPJ_LIVETECH = '05917486000140';
const CFOPS_VALIDOS = ['5915', '6915'];
const SIMILARIDADE_MIN = 30; // abaixo disso, tratamos como "produto não reconhecido"

function limpar(str) {
  return (str || '').toString().replace(/[^a-zA-Z0-9]/g, '').toUpperCase();
}

function palavras(str) {
  return (str || '').toUpperCase().match(/[A-Z0-9]{3,}/g) || [];
}

function compararDescricao(descCrg, descNota) {
  const pCrg = palavras(descCrg);
  const pNota = palavras(descNota);
  if (pCrg.length === 0) return 0;
  let matches = 0;
  for (const p of pCrg) {
    if (pNota.some(n => n.includes(p) || p.includes(n))) matches++;
  }
  return Math.round((matches / pCrg.length) * 100);
}

function numVal(v) {
  if (v === null || v === undefined || v === '') return null;
  const s = v.toString().replace(/[R$\s]/g, '').trim();
  if (s.includes(',')) {
    return parseFloat(s.replace(/\./g, '').replace(',', '.'));
  }
  return parseFloat(s);
}

// ── 1. VALIDAÇÃO POR NOTA ───────────────────────────────
const resultadosNotas = [];

for (let i = 0; i < notas.length; i++) {
  const nota = notas[i];
  const checks = [];

  const cnpjOk = limpar(nota.cnpj_destinatario) === CNPJ_LIVETECH;
  checks.push({
    item: 'CNPJ Destinatário',
    esperado: '05.917.486/0001-40',
    recebido: nota.cnpj_destinatario,
    resultado: cnpjOk ? 'OK' : 'ERRO'
  });

  const cfop = nota.cfop || (nota.produtos?.[0]?.cfop) || '';
  const cfopOk = CFOPS_VALIDOS.includes(cfop.trim());
  checks.push({
    item: 'CFOP',
    esperado: '5915 ou 6915',
    recebido: cfop,
    resultado: cfopOk ? 'OK' : 'ERRO'
  });

  const nat = (nota.natureza || '').toLowerCase();
  const natOk = nat.includes('remessa') || nat.includes('conserto') || nat.includes('garantia');
  checks.push({
    item: 'Natureza da Operação',
    esperado: 'Remessa / Conserto / Garantia',
    recebido: nota.natureza || 'Não identificada',
    resultado: natOk ? 'OK' : 'ERRO'
  });

  checks.push({
    item: 'CRG na Nota',
    esperado: 'Presente',
    recebido: nota.crg || 'Não encontrado',
    resultado: nota.crg ? 'OK' : 'ALERTA'
  });

  const prods = nota.produtos || [];
  const impostosZerados = prods.length === 0 || prods.every(p =>
    numVal(p.bc_icms) === 0 && numVal(p.vlr_icms) === 0 && numVal(p.vlr_ipi) === 0
  );
  checks.push({
    item: 'Impostos Zerados',
    esperado: 'ICMS, IPI = 0',
    recebido: impostosZerados ? 'Todos zerados' : 'IMPOSTOS DESTACADOS',
    resultado: impostosZerados ? 'OK' : 'ERRO'
  });

  const temErroNota = checks.some(c => c.resultado === 'ERRO');
  const temAlertaNota = checks.some(c => c.resultado === 'ALERTA');

  resultadosNotas.push({
    nota_index: i + 1,
    numero_nf: nota.numero_nf,
    crg: nota.crg || '',
    status_nota: temErroNota ? 'REPROVADO' : (temAlertaNota ? 'COM ALERTAS' : 'OK'),
    validacoes: checks,
    produtos: prods
  });
}

// ── 2. SOMAR QUANTIDADES DE TODAS AS NOTAS POR PRODUTO ──
const somaPorProduto = {};

for (const nota of notas) {
  for (const prod of (nota.produtos || [])) {
    let melhorCrg = null;
    let melhorScore = 0;

    for (const crg of produtosCrg) {
      const score = compararDescricao(crg.descricao, prod.descricao);
      if (score > melhorScore) {
        melhorScore = score;
        melhorCrg = crg;
      }
    }

    const chave = melhorCrg ? melhorCrg.cod_prod : prod.codigo;

    if (!somaPorProduto[chave]) {
      somaPorProduto[chave] = {
        cod_prod_crg: melhorCrg ? melhorCrg.cod_prod : '',
        descricao_crg: melhorCrg ? melhorCrg.descricao : '',
        qtd_crg: melhorCrg ? (parseInt(melhorCrg.quantidade) || 0) : 0,
        vlr_unit_crg: melhorCrg ? numVal(melhorCrg.valor_unitario) : null,
        qtd_notas_total: 0,
        notas_detalhe: [],
        melhor_similaridade: 0,
        reconhecido: false
      };
    }

    const qtdProd = parseInt(prod.quantidade) || 0;
    somaPorProduto[chave].qtd_notas_total += qtdProd;
    if (melhorScore > somaPorProduto[chave].melhor_similaridade) {
      somaPorProduto[chave].melhor_similaridade = melhorScore;
    }
    somaPorProduto[chave].reconhecido = somaPorProduto[chave].melhor_similaridade >= SIMILARIDADE_MIN;

    somaPorProduto[chave].notas_detalhe.push({
      nf: notas.find(n => (n.produtos || []).includes(prod))?.numero_nf || '',
      codigo_nota: prod.codigo,
      descricao_nota: prod.descricao,
      quantidade: qtdProd,
      valor_unitario: prod.valor_unitario,
      similaridade: melhorScore
    });
  }
}

// ── 3. COMPARAÇÃO CONSOLIDADA ───────────────────────────
const comparacaoConsolidada = [];

for (const [chave, dadosProd] of Object.entries(somaPorProduto)) {
  const qtdOk = dadosProd.qtd_notas_total === dadosProd.qtd_crg;
  const qtdParcial = dadosProd.qtd_notas_total < dadosProd.qtd_crg;
  const qtdExcede = dadosProd.qtd_notas_total > dadosProd.qtd_crg;

  let statusQtd;
  if (!dadosProd.reconhecido) {
    statusQtd = 'Não aplicável (produto não reconhecido)';
  } else if (qtdOk) {
    statusQtd = `${dadosProd.qtd_notas_total} = ${dadosProd.qtd_crg}`;
  } else if (qtdParcial) {
    statusQtd = `Parcial: ${dadosProd.qtd_notas_total} de ${dadosProd.qtd_crg} (faltam ${dadosProd.qtd_crg - dadosProd.qtd_notas_total})`;
  } else {
    statusQtd = `Excede: ${dadosProd.qtd_notas_total} > ${dadosProd.qtd_crg}`;
  }

  const detalheNfs = dadosProd.notas_detalhe.map(d =>
    `NF ${d.nf}: ${d.quantidade} un (R$${d.valor_unitario})`
  ).join(' + ');

  const valoresNotas = dadosProd.notas_detalhe.map(d => numVal(d.valor_unitario)).filter(v => v !== null);
  let statusValor = 'Sem comparação';
  if (dadosProd.reconhecido && valoresNotas.length > 0 && dadosProd.vlr_unit_crg !== null) {
    const todosOk = valoresNotas.every(v => {
      const diff = Math.abs(v - dadosProd.vlr_unit_crg);
      return dadosProd.vlr_unit_crg > 0 ? (diff / dadosProd.vlr_unit_crg) <= 0.05 : diff === 0;
    });

    if (todosOk) {
      statusValor = `Todos aprox. R$${dadosProd.vlr_unit_crg.toFixed(2)}`;
    } else {
      const lista = valoresNotas.map(v => `R$${v.toFixed(2)}`).join(', ');
      statusValor = `Notas: ${lista} | CRG: R$${dadosProd.vlr_unit_crg.toFixed(2)}`;
    }
  }

  const recebidoRepresentante = dadosProd.notas_detalhe[0] || {};

  comparacaoConsolidada.push({
    produto_crg: dadosProd.reconhecido
      ? `${dadosProd.cod_prod_crg} - ${dadosProd.descricao_crg}`
      : 'Produto não identificado no CRG',
    similaridade: `${dadosProd.melhor_similaridade}% (${dadosProd.reconhecido ? 'OK' : 'ERRO'})`,
    quantidade_total: statusQtd,
    composicao: detalheNfs,
    valor_unitario: statusValor,

    reconhecido: dadosProd.reconhecido,
    produto_recebido: {
      codigo: recebidoRepresentante.codigo_nota || '',
      descricao: recebidoRepresentante.descricao_nota || '',
      quantidade_total: dadosProd.qtd_notas_total,
      valor_unitario: recebidoRepresentante.valor_unitario || ''
    },
    produto_esperado_crg: dadosProd.reconhecido ? {
      codigo: dadosProd.cod_prod_crg,
      descricao: dadosProd.descricao_crg,
      quantidade: dadosProd.qtd_crg,
      valor_unitario: dadosProd.vlr_unit_crg !== null ? dadosProd.vlr_unit_crg.toFixed(2) : ''
    } : null
  });
}

// ── 4. PRODUTOS DO CRG QUE NÃO APARECERAM EM NENHUMA NOTA
const produtosSemNota = produtosCrg.filter(crg => {
  return !Object.values(somaPorProduto).some(s => s.cod_prod_crg === crg.cod_prod);
});

const faltantes = produtosSemNota.map(p => ({
  produto_crg: `${p.cod_prod} - ${p.descricao}`,
  quantidade_esperada: parseInt(p.quantidade) || 0,
  status: 'Nenhuma nota recebida para este produto'
}));

// ── 5. RESUMO GERAL ────────────────────────────────────
const todasNotasOk = resultadosNotas.every(r => !r.status_nota.includes('REPROVADO'));
const temAlertaGeral = resultadosNotas.some(r => r.status_nota.includes('COM ALERTAS'))
  || comparacaoConsolidada.some(c => c.quantidade_total.includes('Parcial') || c.valor_unitario.includes('Notas:'))
  || faltantes.length > 0;
const temErroGeral = resultadosNotas.some(r => r.status_nota.includes('REPROVADO'))
  || comparacaoConsolidada.some(c => c.quantidade_total.includes('Excede'))
  || comparacaoConsolidada.some(c => c.similaridade.includes('ERRO'));

const statusFinal = temErroGeral ? 'REPROVADO' : (temAlertaGeral ? 'APROVADO COM ALERTAS' : 'APROVADO');

return [{
  json: {
    status_final: statusFinal,
    total_notas: notas.length,
    total_produtos_crg: produtosCrg.reduce((acc, p) => acc + (parseInt(p.quantidade) || 0), 0),
    resumo_notas: resultadosNotas.map(r => ({
      nf: r.numero_nf,
      crg: r.crg,
      status: r.status_nota,
      validacoes: r.validacoes
    })),
    comparacao_produtos: comparacaoConsolidada,
    produtos_sem_nota: faltantes.length > 0 ? faltantes : undefined
  }
}];

// ── SEPARAR INPUTS: ValidarNF + TratarLinksPDF ─────────
// Identifica os PDFs pelo tipo marcado na origem, e os dados de
// validação por uma característica própria (status_final), em vez
// de assumir que "tudo que não é PDF" é o item de validação.
// Assim, se um dos dois lados não vier conectado, não quebra.
const allItems = $input.all().map(i => i.json);
const arquivos = allItems.filter(i => i.tipo === 'pdf_sharepoint');
const dados = allItems.find(i => i.tipo !== 'pdf_sharepoint' && i.status_final !== undefined) || {
  status_final: '',
  total_notas: 0,
  total_produtos_crg: 0,
  resumo_notas: [],
  comparacao_produtos: [],
  produtos_sem_nota: []
};

const logoUrl = 'data:image/png;base64,';

function statusBadge(status) {
  const map = {
    'APROVADO': { bg: '#dcfce7', cor: '#166534', borda: '#86efac' },
    'APROVADO COM ALERTAS': { bg: '#fef3c7', cor: '#92400e', borda: '#fbbf24' },
    'REPROVADO': { bg: '#fee2e2', cor: '#991b1b', borda: '#fca5a5' }
  };
  const s = map[dados.status_final] || map['APROVADO COM ALERTAS'];
  return `<span style="display:inline-block;background:${s.bg};color:${s.cor};border:1px solid ${s.borda};padding:6px 16px;border-radius:20px;font-size:14px;font-weight:700;">${dados.status_final}</span>`;
}

function icone(resultado) {
  if (resultado === 'OK') return '✅';
  if (resultado === 'ALERTA') return '⚠️';
  return '❌';
}

// ── TABELAS DE VALIDAÇÃO POR NOTA ───────────────────────
const resumoNotas = dados.resumo_notas || [];
let htmlNotas = '';
for (const nota of resumoNotas) {
  const statusCor = nota.status === 'OK' ? '#166534' : (nota.status === 'ALERTA' ? '#92400e' : '#991b1b');
  const statusBg = nota.status === 'OK' ? '#dcfce7' : (nota.status === 'ALERTA' ? '#fef3c7' : '#fee2e2');

  let rows = '';
  for (const v of (nota.validacoes || [])) {
    rows += `
      <tr>
        <td style="padding:8px 12px;font-size:13px;border-bottom:1px solid #f0f2f5;">${icone(v.resultado)}</td>
        <td style="padding:8px 12px;font-size:13px;border-bottom:1px solid #f0f2f5;font-weight:600;">${v.item}</td>
        <td style="padding:8px 12px;font-size:13px;border-bottom:1px solid #f0f2f5;color:#64748b;">${v.esperado}</td>
        <td style="padding:8px 12px;font-size:13px;border-bottom:1px solid #f0f2f5;">${v.recebido}</td>
      </tr>`;
  }

  htmlNotas += `
    <div style="margin-bottom:24px;">
      <div style="margin-bottom:10px;">
        <span style="font-size:15px;font-weight:700;color:#333;">NF ${nota.nf}</span>
        <span style="display:inline-block;background:${statusBg};color:${statusCor};padding:3px 10px;border-radius:12px;font-size:11px;font-weight:600;margin-left:8px;">${nota.status}</span>
      </div>
      <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e8ecf0;border-radius:8px;overflow:hidden;">
        <tr style="background:#f8fafc;">
          <th style="padding:8px 12px;text-align:left;font-size:11px;color:#64748b;text-transform:uppercase;width:30px;"></th>
          <th style="padding:8px 12px;text-align:left;font-size:11px;color:#64748b;text-transform:uppercase;">Item</th>
          <th style="padding:8px 12px;text-align:left;font-size:11px;color:#64748b;text-transform:uppercase;">Esperado</th>
          <th style="padding:8px 12px;text-align:left;font-size:11px;color:#64748b;text-transform:uppercase;">Recebido</th>
        </tr>
        ${rows}
      </table>
    </div>`;
}

// ── COMPARAÇÃO DE PRODUTOS ──────────────────────────────
// AJUSTE: usa os campos estruturados (reconhecido, produto_recebido,
// produto_esperado_crg) em vez de fazer parse de texto livre — evita
// quebrar quando o produto não é reconhecido no CRG.
let htmlProdutos = '';
for (const p of (dados.comparacao_produtos || [])) {
  const rec = p.produto_recebido || {};
  const esperado = p.produto_esperado_crg;

  if (!p.reconhecido) {
    // ── Produto da nota não corresponde a nenhum item do CRG ──
    htmlProdutos += `
      <div style="background:#f8fafc;border:1px solid #fca5a5;border-radius:8px;padding:16px;margin-bottom:16px;">
        <div style="font-size:13px;font-weight:700;color:#991b1b;margin-bottom:4px;">❌ Produto não identificado no CRG</div>
        <div style="font-size:12px;color:#7a8599;margin-bottom:12px;">
          Este item foi encontrado na Nota Fiscal, mas não corresponde a nenhum produto solicitado neste CRG.
        </div>

        <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;">
          <tr>
            <td style="padding:4px 0;font-size:12px;color:#64748b;width:130px;">Similaridade</td>
            <td style="padding:4px 0;"><span style="background:#fee2e2;color:#991b1b;padding:2px 8px;border-radius:10px;font-weight:600;font-size:12px;">${p.similaridade}</span></td>
          </tr>
          <tr>
            <td style="padding:4px 0;font-size:12px;color:#64748b;">Código na Nota</td>
            <td style="padding:4px 0;font-size:13px;font-weight:600;color:#333;">${rec.codigo || '—'}</td>
          </tr>
          <tr>
            <td style="padding:4px 0;font-size:12px;color:#64748b;">Descrição na Nota</td>
            <td style="padding:4px 0;font-size:13px;color:#333;">${rec.descricao || '—'}</td>
          </tr>
          <tr>
            <td style="padding:4px 0;font-size:12px;color:#64748b;">Quantidade Recebida</td>
            <td style="padding:4px 0;font-size:13px;font-weight:600;color:#333;">${rec.quantidade_total ?? '—'}</td>
          </tr>
        </table>
      </div>`;
    continue;
  }

  // ── Produto reconhecido: mostra comparação recebido x esperado ──
  const simNum = parseInt(p.similaridade) || 0;
  const simCor = simNum >= 50 ? '#166534' : (simNum >= 30 ? '#92400e' : '#991b1b');
  const simBg = simNum >= 50 ? '#dcfce7' : (simNum >= 30 ? '#fef3c7' : '#fee2e2');

  const qtdOk = (p.quantidade_total || '').includes('=');
  const qtdCor = qtdOk ? '#166534' : '#92400e';

  htmlProdutos += `
    <div style="background:#f8fafc;border:1px solid #e8ecf0;border-radius:8px;padding:16px;margin-bottom:16px;">
      <div style="font-size:13px;font-weight:700;color:#1a73e8;margin-bottom:4px;">Produto CRG</div>
      <div style="font-size:13px;color:#333;margin-bottom:12px;">${p.produto_crg}</div>

      <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin-bottom:12px;">
        <tr>
          <td style="padding:4px 0;font-size:12px;color:#64748b;width:120px;">Similaridade</td>
          <td style="padding:4px 0;"><span style="background:${simBg};color:${simCor};padding:2px 8px;border-radius:10px;font-weight:600;font-size:12px;">${p.similaridade}</span></td>
        </tr>
        <tr>
          <td style="padding:4px 0;font-size:12px;color:#64748b;">Qtd Total</td>
          <td style="padding:4px 0;font-size:13px;font-weight:600;color:${qtdCor};">${p.quantidade_total}</td>
        </tr>
        <tr>
          <td style="padding:4px 0;font-size:12px;color:#64748b;">Valor CRG</td>
          <td style="padding:4px 0;font-size:13px;">${p.valor_unitario}</td>
        </tr>
      </table>

      <div style="font-size:12px;font-weight:600;color:#64748b;margin-bottom:6px;text-transform:uppercase;letter-spacing:0.3px;">Recebido x Esperado</div>
      <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e8ecf0;border-radius:6px;overflow:hidden;">
        <tr style="background:#eef2f7;">
          <th style="padding:6px 10px;text-align:left;font-size:11px;color:#64748b;text-transform:uppercase;"></th>
          <th style="padding:6px 10px;text-align:center;font-size:11px;color:#64748b;text-transform:uppercase;">Recebido</th>
          <th style="padding:6px 10px;text-align:center;font-size:11px;color:#64748b;text-transform:uppercase;">Esperado (CRG)</th>
        </tr>
        <tr>
          <td style="padding:6px 10px;font-size:12px;color:#333;border-bottom:1px solid #f0f2f5;">Quantidade</td>
          <td style="padding:6px 10px;font-size:12px;font-weight:700;text-align:center;color:${qtdCor};border-bottom:1px solid #f0f2f5;">${rec.quantidade_total ?? '—'}</td>
          <td style="padding:6px 10px;font-size:12px;font-weight:700;text-align:center;color:#333;border-bottom:1px solid #f0f2f5;">${esperado ? esperado.quantidade : '—'}</td>
        </tr>
        <tr>
          <td style="padding:6px 10px;font-size:12px;color:#333;">Valor Unit.</td>
          <td style="padding:6px 10px;font-size:12px;text-align:center;color:#64748b;">R$ ${rec.valor_unitario || '—'}</td>
          <td style="padding:6px 10px;font-size:12px;text-align:center;color:#64748b;">R$ ${esperado ? esperado.valor_unitario : '—'}</td>
        </tr>
      </table>
    </div>`;
}

// ── PRODUTOS SEM NOTA ───────────────────────────────────
let htmlFaltantes = '';
if (dados.produtos_sem_nota && dados.produtos_sem_nota.length > 0) {
  let rowsFalt = '';
  for (const f of dados.produtos_sem_nota) {
    rowsFalt += `
      <tr>
        <td style="padding:8px 12px;font-size:13px;border-bottom:1px solid #fef2f2;">${f.produto_crg}</td>
        <td style="padding:8px 12px;font-size:13px;border-bottom:1px solid #fef2f2;text-align:center;">${f.quantidade_esperada}</td>
      </tr>`;
  }
  htmlFaltantes = `
    <div style="margin-top:20px;">
      <div style="font-size:14px;font-weight:700;color:#991b1b;margin-bottom:10px;">Produtos do CRG sem Nota Recebida</div>
      <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #fca5a5;border-radius:8px;overflow:hidden;">
        <tr style="background:#fee2e2;">
          <th style="padding:8px 12px;text-align:left;font-size:11px;color:#991b1b;text-transform:uppercase;">Produto</th>
          <th style="padding:8px 12px;text-align:center;font-size:11px;color:#991b1b;text-transform:uppercase;width:80px;">Qtd</th>
        </tr>
        ${rowsFalt}
      </table>
    </div>`;
}

// ── ARQUIVOS PDF (SHAREPOINT) ───────────────────────────
let htmlArquivos = '';
if (arquivos.length > 0) {
  let rowsArq = '';
  for (const arq of arquivos) {
    const nome = arq.nome || 'Arquivo';
    const tamanho = arq.tamanho ? (arq.tamanho / 1024).toFixed(0) + ' KB' : '';
    const link = arq.link || '';
    rowsArq += `
      <tr>
        <td style="padding:10px 12px;font-size:13px;border-bottom:1px solid #f0f2f5;vertical-align:middle;">
          <span style="color:#dc2626;font-size:18px;vertical-align:middle;">📄</span>
          <span style="margin-left:6px;color:#333;font-weight:500;">${nome}</span>
          ${tamanho ? `<span style="margin-left:6px;font-size:11px;color:#94a3b8;">(${tamanho})</span>` : ''}
        </td>
        <td style="padding:10px 12px;border-bottom:1px solid #f0f2f5;text-align:right;vertical-align:middle;">
          <a href="${link}" target="_blank" style="display:inline-block;background:#1a73e8;color:#ffffff;padding:8px 18px;border-radius:6px;font-size:12px;font-weight:600;text-decoration:none;letter-spacing:0.3px;">⬇ Download</a>
        </td>
      </tr>`;
  }

  htmlArquivos = `
    <div style="margin-top:24px;">
      <div style="font-size:16px;font-weight:700;color:#333;margin-bottom:14px;border-bottom:2px solid #e8ecf0;padding-bottom:8px;">Documentos Anexos</div>
      <table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #e8ecf0;border-radius:8px;overflow:hidden;">
        <tr style="background:#f8fafc;">
          <th style="padding:8px 12px;text-align:left;font-size:11px;color:#64748b;text-transform:uppercase;">Arquivo</th>
          <th style="padding:8px 12px;text-align:right;font-size:11px;color:#64748b;text-transform:uppercase;width:120px;">Ação</th>
        </tr>
        ${rowsArq}
      </table>
    </div>`;
}

let crg = '';
try { crg = String($('PegarCRG').first().json.crg || '').replace(/^CRG-/i, '').trim(); } catch (e) { crg = ''; }
if (!crg) crg = String(resumoNotas[0]?.crg || '').replace(/^CRG-/i, '').trim();
const temValidacao = !!dados.status_final;

const htmlHeaderTitulo = temValidacao ? 'Validação de nota fiscal' : 'Documentos anexos';

const htmlStatusBadge = temValidacao ? statusBadge(dados.status_final) : '';

const htmlIntro = temValidacao ? `
  <div style="background:#eff6ff;border-left:4px solid #1a73e8;border-radius:0 8px 8px 0;padding:14px 18px;margin-bottom:24px;">
    <div style="font-size:13px;color:#1e40af;line-height:1.6;">
      O sistema realizou a validação automática de <strong>${dados.total_notas} nota(s) fiscal(is)</strong> recebida(s) do cliente para o processo <strong>CRG-${crg}</strong>.
      Revise os resultados abaixo e aprove ou conteste o recebimento.
    </div>
  </div>

  <table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;">
    <tr>
      <td style="padding:6px;text-align:center;width:50%;">
        <div style="background:#f8fafc;border-radius:8px;padding:14px 8px;border:1px solid #e8ecf0;">
          <div style="font-size:24px;font-weight:700;color:#1a73e8;line-height:1;">${dados.total_notas}</div>
          <div style="font-size:10px;color:#7a8599;margin-top:5px;text-transform:uppercase;letter-spacing:0.5px;">Notas Recebidas</div>
        </div>
      </td>
      <td style="padding:6px;text-align:center;width:50%;">
        <div style="background:#f8fafc;border-radius:8px;padding:14px 8px;border:1px solid #e8ecf0;">
          <div style="font-size:24px;font-weight:700;color:#16a34a;line-height:1;">${dados.total_produtos_crg}</div>
          <div style="font-size:10px;color:#7a8599;margin-top:5px;text-transform:uppercase;letter-spacing:0.5px;">Produtos no CRG</div>
        </div>
      </td>
    </tr>
  </table>

  <div style="font-size:16px;font-weight:700;color:#333;margin-bottom:14px;border-bottom:2px solid #e8ecf0;padding-bottom:8px;">Validação por Nota Fiscal</div>
  ${htmlNotas}

  <div style="font-size:16px;font-weight:700;color:#333;margin-bottom:14px;border-bottom:2px solid #e8ecf0;padding-bottom:8px;">Comparação de Produtos</div>
  ${htmlProdutos}

  ${htmlFaltantes}
