  const map = {};
  lista.forEach(r => {
    const cod = (r.COD_PROD || 'SEM CÓDIGO').trim();
    const descNormalizada = (r.DESCRICAO || '').trim().toUpperCase().replace(/\s+/g, ' ');
    const key = descNormalizada || cod;

    if (!map[key]) {
      map[key] = {
        COD_PROD: cod,
        DESCRICAO: (r.DESCRICAO || '').trim(),
        VALOR_TOTAL: 0,
        QTD: 0
      };
    }
    map[key].QTD++;
    map[key].VALOR_TOTAL += Number(r.VALOR_UNITARIO) || 0;
  });
  return Object.values(map).map(p => ({
    ...p,
    VALOR_UNITARIO: p.QTD > 0 ? p.VALOR_TOTAL / p.QTD : 0
  }));
}

