parameters.jsCode:
// Destinatários: para = e-mail do formulário (se vazio, o SAC); cc = e-mails em cópia do formulário + SAC (sem repetir)
const SAC_EMAIL = 'SAC@wdcnet.com.br';
function destinatarios(email, copia) {
  const lista = (s) => String(s || '').split(/[;,]+/).map(x => x.trim()).filter(Boolean);
  const igual = (a, b) => a.toLowerCase() === b.toLowerCase();
  const unicos = (arr) => arr.filter((x, i) => arr.findIndex(y => igual(x, y)) === i);
  const para = unicos(lista(email));
  const paraFinal = para.length ? para : [SAC_EMAIL];
  const cc = unicos([...lista(copia), SAC_EMAIL]).filter(x => !paraFinal.some(p => igual(p, x)));
  return { para: paraFinal.join(';'), cc: cc.join(';') };
}
// ID do processo vem do próprio input:
//  - caminho Webhook/WhatsApp: retorno do nó SOLICITACAO (ID + PROCESSO)
//  - caminho Retorno de planilha: linha da solicitação vinda do nó 'Assumir solicitação'
const entrada = $input.first().json;
const idProcesso = entrada.PROCESSO || '';

const listaEquipamentos = [];
const listaDuplicados = [];
const seriaisVistos = new Set();
let fabricante = '';
let cnpj = '';
let codCliente = '';
let razaoSocial = '';
let whatsapp = '';
let email = '';
let emailCopia = '';
let protocolo = '';

// Descobre qual trigger rodou (Webhook ou WhatsApp) e recupera o body original
let body = null;
if ($('Webhook').isExecuted) {
  body = $('Webhook').first().json.body;
} else if ($('WhatsApp').isExecuted) {
  body = $('WhatsApp').first().json.body;
}

// RETORNO DE PLANILHA (e-mail do cliente): os dados vêm do banco (input = linha da solicitação)
const ehRetorno = $('Preparar Retorno').isExecuted || entrada.FABRICANTE !== undefined;
if (ehRetorno) {
  fabricante = entrada.FABRICANTE || '';
  cnpj = entrada.CNPJ || '';
  codCliente = entrada.COD_CLIENTE || '';
  razaoSocial = entrada.RAZAO_SOCIAL || '';
  whatsapp = entrada.WHATSAPP || '';
  email = entrada.EMAIL || '';
  emailCopia = entrada.EMAIL_COPIA || '';
  protocolo = entrada.PROTOCOLO || '';
}

// PORTAL / WEBHOOK: e-mails em cópia e lista de seriais já normalizada (JSON, texto ou CSV)
if (!ehRetorno && body) { emailCopia = String(body.email_copia || body.outros_emails || '').trim(); }
const portalVal = $('Validar entrada Portal').isExecuted ? $('Validar entrada Portal').first().json : null;
const listaPortal = (portalVal && portalVal.fonte === 'lista') ? (portalVal.lista || []) : null;

// Lê as linhas de um nó Extract somente se ele foi executado (evita o erro "hasn't been executed")
const lerLinhas = (nome) => {
  const no = $(nome);
  return no.isExecuted ? no.all() : null;
};

if (listaPortal) {
  // PORTAL: seriais vindos em JSON, texto (um por linha) ou CSV
  fabricante = body.fabricante || body['Fabricante'] || '';
  cnpj = body.cnpj || '';
  codCliente = body.cod_cliente || body.codCliente || '';
  razaoSocial = body.razaoSocial || body.razao_social || '';
  whatsapp = body.whatsapp || body.telefone || '';
  email = body.email || '';
  protocolo = body.protocolo || '';
  for (const it of listaPortal) {
    const serial = String(it.serial || '').trim();
    const mac = String(it.mac || '').trim();
    if (!serial) continue;
    const obj = { serial, mac };
    if (seriaisVistos.has(serial)) {
      listaDuplicados.push(obj);
    } else {
      seriaisVistos.add(serial);
      listaEquipamentos.push(obj);
    }
  }
} else if (body && body.lista_serial) {
  // WEBHOOK MANUAL: lista_serial e lista_mac como strings separadas por \n
  fabricante = body.fabricante || '';
  cnpj = body.cnpj || '';
  codCliente = body.cod_cliente || body.codCliente || body.cod_cliente_ || '';
  razaoSocial = body.razaoSocial || body.razao_social || '';
  whatsapp = body.whatsapp || body.telefone || '';
  email = body.email || '';
  protocolo = body.protocolo || '';

  const seriais = (body.lista_serial || '').split(/\\n|\n/).map(s => s.trim()).filter(Boolean);
  const macs = (body.lista_mac || '').split(/\\n|\n/).map(s => s.trim()).filter(Boolean);
  for (let i = 0; i < seriais.length; i++) {
    const serial = seriais[i];
    const mac = macs[i] || '';
    const obj = { serial, mac };
    if (seriaisVistos.has(serial)) {
      listaDuplicados.push(obj);
    } else {
      seriaisVistos.add(serial);
      listaEquipamentos.push(obj);
    }
  }
} else {
  // FORM/PLANILHA: metadados vêm do body (Webhook/WhatsApp) ou do banco (retorno); seriais vêm do Extract
  if (body) {
    fabricante = body['Fabricante'] || body['fabricante'] || '';
    cnpj = body.cnpj || '';
    codCliente = body.cod_cliente || body.codCliente || '';
    razaoSocial = body.razaoSocial || body.razao_social || '';
    whatsapp = body.whatsapp || body.telefone || '';
    email = body.email || '';
    protocolo = body.protocolo || '';
  }

  const nomeExtract = ehRetorno ? 'Extract from File Retorno' : 'Extract from File3';
  const linhas = lerLinhas(nomeExtract);
  if (!linhas) {
    throw new Error(
      `O nó '${nomeExtract}' não foi executado nesta execução. ` +
      `Se estiver testando o nó manualmente, rode o fluxo inteiro antes e escolha no Input o nó pai do caminho testado ` +
      `('Retorno válido?' para o retorno por e-mail, 'SOLICITACAO' para Webhook/WhatsApp).`
    );
  }

  // Nota: o loop começa em i = 1 porque a linha 2 da planilha (títulos das colunas) vira o primeiro item
  for (let i = 1; i < linhas.length; i++) {
    const dadosOriginais = linhas[i].json;
    const chaveSerial = Object.keys(dadosOriginais)[0];
    const serial = dadosOriginais[chaveSerial] ? dadosOriginais[chaveSerial].toString().trim() : '';
    const mac = dadosOriginais['__EMPTY'] ? dadosOriginais['__EMPTY'].toString().trim() : '';
    if (serial) {
      const obj = { serial, mac };
      if (seriaisVistos.has(serial)) {
        listaDuplicados.push(obj);
