// Valida a chamada do portal. Aceita:
//  A) multipart/form-data com "arquivo" (.xlsx/.xls/.csv)  [+ campos de texto]
//  B) multipart ou JSON com os seriais no corpo: "seriais" (array ou texto, um por linha, MAC depois de espaço)
// Chave opcional: preencha API_KEY para exigir o header x-api-key. Vazio = sem exigência.
const API_KEY = '';

const item = $input.first();
const body = item.json.body || {};
const headers = item.json.headers || {};
const bin = item.binary || {};
const erros = [];
const fail = (codigo, resposta) => [{ json: { ok: false, codigo, resposta } }];

if (API_KEY && String(headers['x-api-key'] || '') !== API_KEY) {
  return fail(401, { ok: false, erro: 'nao_autorizado', mensagem: 'Chave de API ausente ou inválida (header x-api-key).' });
}

const norm = (v) => String(v ?? '').trim();
const emailRe = /^[^\s@;,]+@[^\s@;,]+\.[^\s@;,]+$/;

// ---- campos básicos ----
const fabricante = norm(body.fabricante || body.Fabricante);
const cnpjDigitos = norm(body.cnpj).replace(/\D/g, '');
const email = norm(body.email);
const copiaTxt = norm(body.email_copia || body.outros_emails);
const protocolo = norm(body.protocolo);

if (!fabricante) erros.push('fabricante é obrigatório');
if (cnpjDigitos.length < 11) erros.push('cnpj é obrigatório (CNPJ ou CPF, mínimo 11 dígitos)');
if (!emailRe.test(email)) erros.push('email é obrigatório e deve ser um e-mail válido');
if (copiaTxt) {
  if (copiaTxt.length > 500) erros.push('email_copia deve ter no máximo 500 caracteres');
  if (copiaTxt.split(/[;,\s]+/).filter(Boolean).some(e => !emailRe.test(e))) erros.push('email_copia contém e-mail inválido (separe por ; ou ,)');
}
if (protocolo.length > 100) erros.push('protocolo deve ter no máximo 100 caracteres');

// ---- seriais ----
const ehCabecalho = (s) => /^(n[uú]meros? de s[eé]rie|s[eé]rie|serial|sn)$/i.test(norm(s)) || /solicita[cç][aã]o aberta/i.test(norm(s));
const deLinha = (l) => { const p = norm(l).split(/[\s;,\t]+/).filter(Boolean); return p.length ? { serial: p[0], mac: p[1] || '' } : null; };
const deTexto = (t) => norm(t).split(/\r?\n/).map(deLinha).filter(Boolean).filter(x => !ehCabecalho(x.serial));

function deCorpo() {
  const bruto = body.seriais ?? body.lista_serial ?? body.numeros_serie ?? body.numeros_de_serie;
  if (Array.isArray(bruto)) {
    return bruto.map(el => {
      if (el && typeof el === 'object') return { serial: norm(el.serial || el.sn || el.numero_serie), mac: norm(el.mac) };
      return deLinha(el);
    }).filter(x => x && x.serial);
  }
  if (bruto && typeof bruto === 'object') return [];
  if (norm(bruto)) {
    const lista = deTexto(bruto);
    // lista_mac separada (alinhada por posição), se vier
    if (body.lista_mac && !lista.some(x => x.mac)) {
      const macs = String(body.lista_mac).split(/\r?\n/).map(norm);
      lista.forEach((x, i) => { x.mac = macs[i] || ''; });
    }
    return lista;
  }
  return [];
}

function deCsv(texto) {
  const t = String(texto).replace(/^\uFEFF/, '');
  const linhas = t.split(/\r?\n/).filter(l => l.trim() !== '');
  if (!linhas.length) return [];
  const cont = (c) => (linhas[0].match(new RegExp(c === '\t' ? '\t' : '\\' + c, 'g')) || []).length;
  const delim = [';', ',', '\t'].sort((a, b) => cont(b) - cont(a))[0];
  return linhas.map(l => l.split(delim).map(c => c.replace(/^"|"$/g, '').trim()))
    .filter(c => c[0] && !ehCabecalho(c[0]))
    .map(c => ({ serial: c[0], mac: c[1] || '' }));
}

const chave = bin.arquivo ? 'arquivo' : Object.keys(bin)[0];
let fonte = 'lista';
let lista = [];
if (chave) {
  const nomeArq = norm(bin[chave].fileName);
  if (/\.(xlsx|xls)$/i.test(nomeArq)) {
    fonte = 'xlsx';
  } else if (/\.csv$/i.test(nomeArq)) {
    const buf = await this.helpers.getBinaryDataBuffer(0, chave);
    lista = deCsv(buf.toString('utf8'));
  } else {
    erros.push('arquivo deve ser .xlsx, .xls ou .csv');
  }
} else {
  lista = deCorpo();
}

if (fonte === 'lista' && !lista.length && !erros.length) {
  erros.push('informe os números de série: envie "arquivo" (.xlsx/.xls/.csv) ou o campo "seriais" (um por linha, MAC depois de um espaço)');
}
if (lista.some(x => x.serial.length > 50)) erros.push('há número de série com mais de 50 caracteres');

if (erros.length) {
  return fail(400, { ok: false, erro: 'dados_invalidos', mensagem: 'A solicitação não foi criada.', detalhes: erros });
}

const saida = { json: { ...item.json, ok: true, fonte, lista } };
if (fonte === 'xlsx') saida.binary = { arquivo: bin[chave] };   // nome esperado pelo nó Extract from File3
return [saida];
